screen('web-testimonials', dict(viewport='desktop', title='Testimonials wall with logo strip', category='website', type='screen', roles=['social-proof','landing-section'],
  style=['editorial','card-based'], tags=['testimonials','social-proof','avatar','rating','desktop','landing-page'],
  desc='A desktop social-proof section. A headline "Loved by people who ship" and an aggregate rating (4.9 from 2,300 reviews) sit over a three-by-two grid of six quote cards, each with a quote, an avatar, a name and a role; one card is accent-filled and carries a large metric "3× faster reviews". A muted logo strip of six wordmarks closes the section. Built on {words}. Idea: real names and specific outcomes, one highlighted metric card to break the rhythm.'),
  '''<div style="height:100%;padding:54px 80px;display:flex;flex-direction:column">
  <div class="row" style="align-items:flex-end"><div class="col g8"><span class="eyebrow">Customers</span><h1 class="d1" style="font-size:52px">Loved by people <em>who ship.</em></h1></div><div class="sp"></div><div class="col" style="align-items:flex-end"><b class="d2" style="color:var(--accent)">★★★★★</b><span class="small"><b style="color:var(--text)">4.9</b> from 2,300 reviews</span></div></div>
  <div style="display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:1fr;gap:16px;margin-top:30px;flex:1;min-height:0">'''+''.join((f'<div class="card col" style="padding:26px;justify-content:flex-end;background:var(--accent);color:var(--onAccent)"><b class="big" style="font-size:60px">{q}</b><p style="margin-top:8px;opacity:.85;font-size:16px">{n}</p></div>' if r=='metric' else f'<div class="card col g12" style="padding:26px;justify-content:space-between"><p style="font-size:20px;line-height:1.45;letter-spacing:-.01em">“{q}”</p><div class="row g8"><span class="av" style="filter:hue-rotate({h}deg)"></span><div class="col"><b style="font-size:14px">{n}</b><span class="small" style="font-size:12.5px">{r}</span></div></div></div>') for q,n,r,h in [
   ('We replaced three tools in a week. The team actually enjoys using it, which never happens.','Ana Ruiz','Head of Design, Parallax',0),
   ('Reviews that used to take a day now take an hour.','Kenji Watanabe','Staff Engineer, Orbit',80),
   ('3× faster reviews','across 40 product teams in the first quarter','metric',0),
   ('The onboarding is so good I sent it to our PM as a reference.','Lea Martin','Founder, Fieldwork',160),
   ('Finally, analytics our sales team opens without being asked.','Omar Haddad','VP Sales, Northwind',220),
   ('Support answered in eleven minutes on a Sunday. Eleven.','Priya Nair','CTO, Lumen',300)])+'''</div>
  <div class="row" style="justify-content:space-between;padding-top:22px;border-top:1px solid var(--line);color:var(--muted)">'''+''.join(f'<b style="font:{"400 24px var(--serif)" if i%2 else "700 18px var(--sans)"};letter-spacing:-.02em">{n}</b>' for i,n in enumerate(['NORTHWIND','Parallax','ORBIT/AI','Lumen','FIELDWORK','Meridian']))+'''</div></div>''')

