screen('kanban-board', dict(viewport='desktop', title='Kanban board with swimlane columns', category='dashboard', type='screen', roles=['dashboard','list'],
  style=['card-based','data-dense'], tags=['kanban','tasks','productivity','avatar','progress','desktop','sidebar'],
  desc='A desktop project board. A slim top bar has the project name "Website relaunch", a view switcher (Board selected, List, Timeline), stacked avatars and a primary "New task". Four columns — To do, In progress, Review, Done — show counts and cards; each card has a coloured label, title, a checklist progress bar or due date and an assignee avatar, and one card in progress is lifted as if being dragged. Built on {words}. Idea: columns carry state, cards carry only what you need to decide what to do next.'),
  '''<div style="height:100%;display:flex;flex-direction:column">
  <div class="row" style="height:72px;padding:0 28px;border-bottom:1px solid var(--line)"><b class="h3">Website relaunch</b><div class="row" style="margin-left:24px;padding:4px;border-radius:10px;background:var(--surface2)"><span class="pill on" style="border-radius:8px">Board</span><span class="pill" style="background:none">List</span><span class="pill" style="background:none">Timeline</span></div><div class="sp"></div><div class="row" style="gap:0">'''+''.join(f'<span class="av s" style="margin-left:-8px;box-shadow:0 0 0 2px var(--bg);filter:hue-rotate({i*60}deg)"></span>' for i in range(4))+'''</div><button class="btn btn-sm btn-p" style="margin-left:16px">'''+ic('plus')+''' New task</button></div>
  <div class="row" style="flex:1;align-items:stretch;gap:16px;padding:22px 28px;min-height:0">'''+''.join(f'''<div class="col g12" style="flex:1;min-width:0;padding:12px;border-radius:var(--r);background:var(--surface2)"><div class="row"><b style="font-size:14px">{col}</b><span class="small" style="margin-left:8px">{len(cards)}</span><div class="sp"></div>{ic("plus")}</div>{"".join(f'<div class="card col g8" style="padding:14px;{"transform:rotate(-2deg) translateY(-4px);box-shadow:0 24px 40px -18px rgba(0,0,0,.5)" if lift else ""}"><span class="tag" style="align-self:flex-start;{lab}">{tag}</span><b style="font-size:14.5px;line-height:1.3">{t}</b>{f"<div class=&quot;bar-track&quot;><i style=&quot;width:{p}%&quot;></i></div><span class=&quot;small&quot; style=&quot;font-size:12px&quot;>{p//20} of 5 done</span>" if p is not None else f"<span class=&quot;small&quot; style=&quot;font-size:12px&quot;>{due}</span>"}<div class="row"><span class="av s" style="filter:hue-rotate({hu}deg)"></span><div class="sp"></div><span class="small" style="font-size:12px">💬 {cm}</span></div></div>' for tag,lab,t,p,due,hu,cm,lift in cards)}</div>''' for col,cards in [
   ('To do',[('Copy','','Rewrite pricing FAQ',None,'Due Fri',0,2,0),('Research','background:var(--surface2);color:var(--muted)','Interview 5 trial users',None,'Due next week',120,0,0),('Design','','Empty states for search',None,'Due Thu',180,1,0)]),
   ('In progress',[('Design','','Hero illustration v2',60,'',60,5,1),('Build','background:var(--surface2);color:var(--muted)','Pricing toggle animation',40,'',200,1,0),('Copy','','Onboarding email series',20,'',330,0,0)]),
   ('Review',[('Build','background:var(--surface2);color:var(--muted)','Navigation a11y pass',80,'',260,3,0),('Research','background:var(--surface2);color:var(--muted)','Competitor teardown',None,'Needs sign-off',150,6,0)]),
   ('Done',[('Design','','Logo lockups',None,'Done Tue',300,4,0),('Copy','','Homepage headline',None,'Done Mon',30,7,0),('Build','background:var(--surface2);color:var(--muted)','Cookie banner',None,'Done Sun',90,2,0)])])+'''</div></div>''')

