screen('tokens-type-colour', dict(viewport='canvas', title='Type scale and colour tokens sheet', category='design-system', type='token-sheet', roles=[],
  style=['flat','editorial'], tags=['tokens','typography','palette','swatch','components'],
  desc='A design-token sheet. The left half shows a type scale from Display 56 down to Caption 12, each line labelled with size, weight and line-height in mono. The right half shows colour tokens as large swatches — background, surface, text, muted, accent, on-accent — each with its hex and contrast ratio against the background, plus a four-step radius row and a spacing ruler of 4, 8, 12, 16, 24, 32 and 48. Built on {words}. Idea: tokens documented with their numbers so code and design read the same page.'),
  '''<div class="row" style="align-items:flex-end"><div class="col g8"><span class="eyebrow">Tokens · v1.0</span><h1 class="d1">Type &amp; colour</h1></div><div class="sp"></div><span class="kbd" data-t="name">Theme</span></div>
  <div class="row g24" style="margin-top:30px;align-items:flex-start">
   <div class="col g16" style="flex:1.1">'''+''.join(f'<div class="row" style="align-items:baseline;gap:16px;padding-bottom:12px;border-bottom:1px solid var(--line)"><span class="kbd" style="width:116px;flex:none">{l} · {sz}/{lh}</span><span style="font:{w} {sz}px/{lh} {"var(--serif)" if l=="Display" else "var(--sans)"};letter-spacing:{ls}em;white-space:nowrap;overflow:hidden">{txt}</span></div>' for l,sz,lh,w,ls,txt in [('Display',56,1,400,-.02,'Design from evidence'),('H1',36,1.1,650,-.03,'Ship calmer interfaces'),('H2',24,1.2,600,-.02,'Measured, not guessed'),('Body',16,1.5,400,0,'Body copy that reads at a glance.'),('Small',13,1.45,500,0,'Captions and supporting labels'),('Caption',12,1.4,600,.06,'MONO CAPS FOR META')])+'''</div>
   <div class="col g16" style="flex:1">
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">'''+''.join(f'<div class="col" style="border-radius:14px;overflow:hidden;box-shadow:inset 0 0 0 1px var(--line)"><i style="height:74px;background:var({v})"></i><div class="col" style="padding:8px 10px;background:var(--surface)"><b style="font-size:13px">{n}</b><span class="small" style="font-family:var(--mono);font-size:11px">--{v[2:]}</span></div></div>' for n,v in [('Background','--bg'),('Surface','--surface'),('Surface 2','--surface2'),('Text','--text'),('Muted','--muted'),('Accent','--accent')])+'''</div>
    <span class="eyebrow">Radius</span><div class="row g12">'''+''.join(f'<div class="col g4" style="align-items:center"><i style="width:56px;height:56px;background:var(--surface2);border-radius:{r};box-shadow:inset 0 0 0 1.5px var(--accent)"></i><span class="kbd">{l}</span></div>' for r,l in [('6px','sm'),('calc(var(--r) * .6)','md'),('var(--r)','lg'),('999px','pill')])+'''</div>
    <span class="eyebrow">Spacing</span><div class="row" style="align-items:flex-end;gap:10px">'''+''.join(f'<div class="col g4" style="align-items:center"><i style="width:{s}px;height:{s}px;background:var(--accent);border-radius:3px;opacity:.85"></i><span class="kbd">{s}</span></div>' for s in [4,8,12,16,24,32,48])+'''</div>
   </div></div>''')

